import{_ as t,o,c as a,a2 as l}from"./chunks/framework.Crpw6aS5.js";const b=JSON.parse('{"title":"1997年 · 市场与心态","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1997年.md","filePath":"05_quotes/by-year/1997年.md"}'),r={name:"05_quotes/by-year/1997年.md"};function u(s,e,q,c,h,_){return o(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="_1997年-·-市场与心态" tabindex="-1">1997年 · 市场与心态 <a class="header-anchor" href="#_1997年-·-市场与心态" aria-label="Permalink to &quot;1997年 · 市场与心态&quot;">​</a></h1><blockquote><p>在牛市中，必须避免自夸鸭子的错误——在大暴雨后嘎嘎自鸣得意，以为自己的划水技能使它升了天。——巴菲特（67岁）</p></blockquote><p>本页收录1997年致股东信中的经典语录。本年巴菲特以&quot;吃汉堡&quot;的经典比喻阐释了长期投资者应如何正确看待市场波动，并坦承成功消退得更快——规模已成为业绩的最大制约。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>在牛市中，必须避免自夸鸭子的错误——在大暴雨后嘎嘎自鸣得意，以为自己的划水技能使它升了天。</p></blockquote><blockquote><p>如果你计划一生都在吃汉堡，而你又不是牛肉生产者，你应该希望牛肉价格更高还是更低？……如果你预计在未来五年是净储蓄者，你应该希望股票市场在这段时期更高还是更低？许多投资者会答错。</p></blockquote><blockquote><p>当你在头条中看到&quot;投资者因市场下跌而损失&quot;时，请微笑。在你的脑海中将其编辑为&quot;退投资者因市场下跌而损失——但投资者获益。&quot;</p></blockquote><blockquote><p>对于任何配置资本的人来说，没有什么比成功消退得更快。</p></blockquote><blockquote><p>我们宁愿要参差不齐的15%，也不要平滑的12%。由于大多数管理者倾向于平滑，我们享有了一种我们努力最大化的竞争优势。</p></blockquote><blockquote><p>等待大展宏图的球意味着进入名人堂；不加选择地挥棒则意味着进入小联盟。</p></blockquote><blockquote><p>一份糟糕的再保险合同就像地狱：进去容易，出来不可能。</p></blockquote><blockquote><p>我们搞砸时，请试着友善地对待我们。和克林顿总统一样，我们会感受到你们的痛苦：查理·芒格家族超过90%的净资产和沃伦·巴菲特家族超过99%的净资产都集中在伯克希尔。</p></blockquote><blockquote><p>只是在童话故事中，皇帝才会被告知他们是裸体的。</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1997年伯克希尔每股账面价值增长34.1%，但标普500涨幅相近，巴菲特坦承&quot;嘎嘎&quot;——牛市中难以超越指数。本年收购明星家具和国际乳品皇后，白银和零息国债等非常规投资首次亮相。巴菲特用&quot;鸭子与暴雨&quot;和&quot;汉堡&quot;的比喻，深刻阐释了长期投资者应对市场波动的正确心态。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-1997年-翻译-·-01-letters-1997年-核心总结-·-01-letters-1997年-思维导图" tabindex="-1"><a href="/01_letters/1997年/翻译.html">01_letters/1997年/翻译</a> · <a href="/01_letters/1997年/核心总结.html">01_letters/1997年/核心总结</a> · <a href="/01_letters/1997年/思维导图.html">01_letters/1997年/思维导图</a> <a class="header-anchor" href="#_01-letters-1997年-翻译-·-01-letters-1997年-核心总结-·-01-letters-1997年-思维导图" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/1997年/翻译]] · [[→ 核心总结|01_letters/1997年/核心总结]] · [[→ 思维导图|01_letters/1997年/思维导图]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/1997年/翻译.html">/01_letters/1997年/翻译</a></li></ul>',22)])])}const p=t(r,[["render",u]]);export{b as __pageData,p as default};
